<script setup lang="ts">const shop=useShop();const customers=computed(()=>{const map=new Map<string,{name:string;email:string;orders:number;spent:number}>();shop.orders.forEach(o=>{const current=map.get(o.customer.email)||{name:o.customer.name,email:o.customer.email,orders:0,spent:0};current.orders++;current.spent+=o.total;map.set(o.customer.email,current)});if(shop.user&&!map.has(shop.user.email))map.set(shop.user.email,{name:shop.user.name,email:shop.user.email,orders:0,spent:0});return [...map.values()]})</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Admin demo</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Customers<span class="text-brand">.</span></h1><p class="mt-3 text-sm text-gray-500">Derived from the demo profile and local demo orders only.</p><div v-if="customers.length" class="mt-7 overflow-x-auto rounded-2xl border border-gray-100"><table class="w-full min-w-[600px] text-left text-sm"><thead class="bg-mist text-xs uppercase tracking-wider text-gray-500"><tr><th class="p-4">Customer</th><th class="p-4">Email</th><th class="p-4">Orders</th><th class="p-4">Demo spend</th></tr></thead><tbody><tr v-for="c in customers" :key="c.email" class="border-t border-gray-100"><td class="p-4 font-semibold">{{ c.name }}</td><td class="p-4">{{ c.email }}</td><td class="p-4">{{ c.orders }}</td><td class="p-4">${{ c.spent.toFixed(2) }}</td></tr></tbody></table></div><EmptyState v-else title="No demo customers yet" description="Create a demo account or place an order to see customers here." to="/register" action-label="Create demo account"/><NuxtLink to="/admin" class="mt-6 inline-block text-xs font-semibold text-gray-500">← Back to dashboard</NuxtLink></div></template>
